6	type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
7	
8	async function recalculateProductCost(supabase: SupabaseServerClient, productId: string) {
9	  const { data: items } = await supabase
10	    .from("product_recipes")
11	    .select("qty, ingredients(unit_cost)")
12	    .eq("product_id", productId);
13	
14	  const totalCost = (items ?? []).reduce((sum, item) => {
15	    const ingredient = item.ingredients as unknown as { unit_cost: number } | null;
16	    return sum + Number(ingredient?.unit_cost ?? 0) * Number(item.qty);
17	  }, 0);
18	
19	  await supabase.from("products").update({ cost: totalCost }).eq("id", productId);
20	}
