24	export async function addRecipeItem(
25	  businessId: string,
26	  productId: string,
27	  _prevState: RecipeState,
28	  formData: FormData,
29	): Promise<RecipeState> {
30	  const ingredientId = formData.get("ingredientId") as string;
31	  const qtyRaw = formData.get("qty") as string;
32	  const qty = Number(qtyRaw);
33	
34	  if (!ingredientId) {
35	    return { error: "Pilih bahan baku dulu." };
36	  }
37	  if (!qtyRaw || Number.isNaN(qty) || qty <= 0) {
38	    return { error: "Jumlah harus angka lebih dari 0." };
39	  }
40	
41	  const supabase = await createClient();
42	
43	  const { data: ingredient } = await supabase
44	    .from("ingredients")
45	    .select("unit")
46	    .eq("id", ingredientId)
47	    .single();
48	
49	  if (!ingredient) {
50	    return { error: "Bahan baku tidak ditemukan." };
51	  }
52	
53	  const { error: insertError } = await supabase.from("product_recipes").insert({
54	    product_id: productId,
55	    ingredient_id: ingredientId,
56	    qty,
57	    unit: ingredient.unit,
58	  });
59	
60	  if (insertError) {
61	    return { error: insertError.message };
62	  }
63	
64	  await recalculateProductCost(supabase, productId);
65	
66	  revalidatePath(`/business/${businessId}/products/${productId}/recipe`);
67	  return { error: null };
68	}
