3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { logActivity } from "@/lib/activity-log";
6	
7	type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
8	
9	const PURCHASE_INGREDIENT_CATEGORY = "Pembelian Bahan Baku";
10	const PURCHASE_PRODUCT_CATEGORY = "Pembelian Barang Dagang";
11	
12	// Kategori pengeluaran non-pembelian → akun beban di Daftar Akun. Kategori di
13	// luar daftar ini (harusnya tidak terjadi karena dropdown form sudah dibatasi)
14	// jatuh ke "Beban Lain-lain".
15	const EXPENSE_CATEGORY_ACCOUNT: Record<string, string> = {
16	  Sewa: "5-102",
17	  "Gaji & Upah": "5-100",
18	  "Listrik & Air": "5-101",
19	  Marketing: "5-103",
20	  Perlengkapan: "5-104",
21	  "Lain-lain": "5-999",
22	};
23	
24	async function postExpenseJournal(
25	  supabase: SupabaseServerClient,
26	  businessId: string,
27	  date: string,
28	  category: string,
29	  amount: number,
30	  isPurchase: boolean,
31	) {
32	  const debitAccount = isPurchase ? "1-200" : EXPENSE_CATEGORY_ACCOUNT[category] ?? "5-999";
33	  await supabase.rpc("post_journal_entry", {
34	    p_business_id: businessId,
35	    p_date: date,
36	    p_description: `Pengeluaran: ${category}`,
37	    p_lines: [
38	      { account_code: debitAccount, debit: amount, credit: 0 },
39	      { account_code: "1-001", debit: 0, credit: amount },
40	    ],
41	  });
42	}
