44	export type ExpenseState = { error: string | null };
45	
46	export async function addExpense(
47	  businessId: string,
48	  _prevState: ExpenseState,
49	  formData: FormData,
50	): Promise<ExpenseState> {
51	  const date = formData.get("date") as string;
52	  const category = (formData.get("category") as string)?.trim();
53	  const amountRaw = formData.get("amount") as string;
54	  const note = (formData.get("note") as string)?.trim();
55	
56	  if (!date) {
57	    return { error: "Tanggal wajib diisi." };
58	  }
59	  if (!category) {
60	    return { error: "Kategori wajib diisi." };
61	  }
62	
63	  const amount = Number(amountRaw);
64	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
65	    return { error: "Jumlah harus angka lebih dari 0." };
66	  }
67	
68	  const isIngredientPurchase = category === PURCHASE_INGREDIENT_CATEGORY;
69	  const isProductPurchase = category === PURCHASE_PRODUCT_CATEGORY;
70	
71	  const supabase = await createClient();
72	
73	  let ingredientId: string | null = null;
74	  let productId: string | null = null;
75	  let qty: number | null = null;
76	
77	  if (isIngredientPurchase) {
78	    ingredientId = formData.get("ingredientId") as string;
79	    qty = Number(formData.get("qty") as string);
80	    if (!ingredientId) {
81	      return { error: "Pilih bahan yang dibeli." };
82	    }
83	    if (!qty || Number.isNaN(qty) || qty <= 0) {
84	      return { error: "Qty dibeli harus angka lebih dari 0." };
85	    }
86	
87	    const { data: ingredient } = await supabase
88	      .from("ingredients")
89	      .select("id, business_id, stock, unit_cost")
90	      .eq("id", ingredientId)
91	      .single();
92	
93	    if (!ingredient || ingredient.business_id !== businessId) {
94	      return { error: "Bahan baku tidak ditemukan." };
95	    }
96	
97	    const oldValue = Number(ingredient.stock) * Number(ingredient.unit_cost);
98	    const newStock = Number(ingredient.stock) + qty;
99	    const newUnitCost =
100	      newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(ingredient.unit_cost);
101	
102	    const { error: updateError } = await supabase
103	      .from("ingredients")
104	      .update({ stock: newStock, unit_cost: newUnitCost })
105	      .eq("id", ingredientId);
106	
107	    if (updateError) {
108	      return { error: updateError.message };
109	    }
110	
111	    if (newUnitCost !== Number(ingredient.unit_cost)) {
112	      await supabase.from("ingredient_price_history").insert({
113	        business_id: businessId,
114	        ingredient_id: ingredientId,
115	        unit_cost: newUnitCost,
116	        source: "pembelian",
117	      });
118	    }
119	  }
120	
121	  if (isProductPurchase) {
122	    productId = formData.get("productId") as string;
123	    qty = Number(formData.get("qty") as string);
124	    if (!productId) {
125	      return { error: "Pilih produk yang dibeli." };
126	    }
127	    if (!qty || Number.isNaN(qty) || qty <= 0) {
128	      return { error: "Qty dibeli harus angka lebih dari 0." };
129	    }
130	
131	    const { data: product } = await supabase
132	      .from("products")
133	      .select("id, business_id, stock, cost")
134	      .eq("id", productId)
135	      .single();
136	
137	    if (!product || product.business_id !== businessId) {
138	      return { error: "Produk tidak ditemukan." };
139	    }
140	
141	    const oldValue = Number(product.stock) * Number(product.cost);
142	    const newStock = Number(product.stock) + qty;
143	    const newCost = newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(product.cost);
144	
145	    const { error: updateError } = await supabase
146	      .from("products")
147	      .update({ stock: newStock, cost: newCost })
148	      .eq("id", productId);
149	
150	    if (updateError) {
151	      return { error: updateError.message };
152	    }
153	  }
154	
155	  const { error } = await supabase.from("expenses").insert({
156	    business_id: businessId,
157	    date,
158	    category,
159	    amount,
160	    note: note || null,
161	    ingredient_id: ingredientId,
162	    product_id: productId,
163	    qty,
164	  });
165	
166	  if (error) {
167	    return { error: error.message };
168	  }
169	
170	  await postExpenseJournal(
171	    supabase,
172	    businessId,
173	    date,
174	    category,
175	    amount,
176	    isIngredientPurchase || isProductPurchase,
177	  );
178	
179	  await logActivity(
180	    supabase,
181	    businessId,
182	    "sistem",
183	    "info",
184	    `Pengeluaran: ${category}`,
185	    `Rp${amount.toLocaleString("id-ID")}${note ? ` · ${note}` : ""}`,
186	  );
187	  revalidatePath(`/business/${businessId}/finance`);
188	  return { error: null };
189	}
