191	export async function deleteExpense(businessId: string, expenseId: string) {
192	  const supabase = await createClient();
193	  // Menghapus pengeluaran tidak membalik stok/harga bahan atau produk secara
194	  // otomatis — harga rata-rata tertimbang sudah bercampur dengan pembelian
195	  // lain. Kalau salah input, sesuaikan stok manual di halaman terkait.
196	  const { data: expense } = await supabase
197	    .from("expenses")
198	    .select("category, amount")
199	    .eq("id", expenseId)
200	    .eq("business_id", businessId)
201	    .maybeSingle();
202	  await supabase.from("expenses").delete().eq("id", expenseId).eq("business_id", businessId);
203	  if (expense) {
204	    await logActivity(
205	      supabase,
206	      businessId,
207	      "sistem",
208	      "warning",
209	      `Pengeluaran dihapus: ${expense.category}`,
210	      `Rp${Number(expense.amount).toLocaleString("id-ID")}`,
211	    );
212	  }
213	  revalidatePath(`/business/${businessId}/finance`);
214	}
