216	export async function setMerchantFeePercent(businessId: string, method: string, feePercent: number) {
217	  const supabase = await createClient();
218	  await supabase
219	    .from("merchant_fees")
220	    .upsert(
221	      { business_id: businessId, method, fee_percent: feePercent },
222	      { onConflict: "business_id,method" },
223	    );
224	  revalidatePath(`/business/${businessId}/finance`);
225	}
