227	export type ReconciliationState = { error: string | null };
228	
229	export async function addReconciliation(
230	  businessId: string,
231	  _prevState: ReconciliationState,
232	  formData: FormData,
233	): Promise<ReconciliationState> {
234	  const date = formData.get("date") as string;
235	  const method = (formData.get("method") as string)?.trim();
236	  const amountRaw = formData.get("amount") as string;
237	  const note = (formData.get("note") as string)?.trim();
238	
239	  if (!date) {
240	    return { error: "Tanggal wajib diisi." };
241	  }
242	  if (!method) {
243	    return { error: "Pilih metode pembayaran." };
244	  }
245	
246	  const amount = Number(amountRaw);
247	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
248	    return { error: "Jumlah harus angka lebih dari 0." };
249	  }
250	
251	  const supabase = await createClient();
252	
253	  const { data: openShift } = await supabase
254	    .from("shifts")
255	    .select("id")
256	    .eq("business_id", businessId)
257	    .is("closed_at", null)
258	    .limit(1)
259	    .maybeSingle();
260	
261	  if (openShift) {
262	    return { error: "Tutup shift dulu sebelum mencatat rekonsiliasi." };
263	  }
264	
265	  const { error } = await supabase.from("reconciliations").insert({
266	    business_id: businessId,
267	    date,
268	    method,
269	    actual_amount: amount,
270	    note: note || null,
271	  });
272	
273	  if (error) {
274	    return { error: error.message };
275	  }
276	
277	  revalidatePath(`/business/${businessId}/finance`);
278	  return { error: null };
279	}
