281	export type OpeningInventoryState = { error: string | null };
282	
283	export async function setOpeningInventory(
284	  businessId: string,
285	  anchorDate: string,
286	  _prevState: OpeningInventoryState,
287	  formData: FormData,
288	): Promise<OpeningInventoryState> {
289	  const valueRaw = formData.get("value") as string;
290	  const value = Number(valueRaw);
291	
292	  if (!valueRaw || Number.isNaN(value) || value < 0) {
293	    return { error: "Nilai persediaan harus angka dan tidak boleh negatif." };
294	  }
295	
296	  const supabase = await createClient();
297	  const { error } = await supabase
298	    .from("inventory_snapshots")
299	    .upsert(
300	      { business_id: businessId, date: anchorDate, value, manual: true },
301	      { onConflict: "business_id,date" },
302	    );
303	
304	  if (error) {
305	    return { error: error.message };
306	  }
307	
308	  revalidatePath(`/business/${businessId}/finance`);
309	  return { error: null };
310	}
