184	export type AddPaymentState = { error: string | null };
185	
186	export async function addPurchasePayment(
187	  businessId: string,
188	  purchaseId: string,
189	  _prevState: AddPaymentState,
190	  formData: FormData,
191	): Promise<AddPaymentState> {
192	  const date = formData.get("date") as string;
193	  const amountRaw = formData.get("amount") as string;
194	  const note = (formData.get("note") as string)?.trim();
195	
196	  if (!date) {
197	    return { error: "Tanggal wajib diisi." };
198	  }
199	
200	  const amount = Number(amountRaw);
201	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
202	    return { error: "Jumlah bayar harus angka lebih dari 0." };
203	  }
204	
205	  const supabase = await createClient();
206	
207	  const { data: purchase } = await supabase
208	    .from("purchases")
209	    .select("id, business_id, amount, paid_amount, ingredient_id, product_id")
210	    .eq("id", purchaseId)
211	    .eq("business_id", businessId)
212	    .single();
213	
214	  if (!purchase) {
215	    return { error: "Data pembelian tidak ditemukan." };
216	  }
217	
218	  const sisaUtang = Number(purchase.amount) - Number(purchase.paid_amount);
219	  if (amount > sisaUtang) {
220	    return { error: `Jumlah bayar melebihi sisa utang (${sisaUtang.toLocaleString("id-ID")}).` };
221	  }
222	
223	  const newPaidAmount = Number(purchase.paid_amount) + amount;
224	
225	  const { error: updateError } = await supabase
226	    .from("purchases")
227	    .update({ paid_amount: newPaidAmount })
228	    .eq("id", purchaseId);
229	
230	  if (updateError) {
231	    return { error: updateError.message };
232	  }
233	
234	  const { error } = await supabase.from("purchase_payments").insert({
235	    business_id: businessId,
236	    purchase_id: purchaseId,
237	    date,
238	    amount,
239	    note: note || null,
240	  });
241	
242	  if (error) {
243	    return { error: error.message };
244	  }
245	
246	  await supabase.rpc("post_journal_entry", {
247	    p_business_id: businessId,
