142	export type AdjustStockResult = { error: string | null };
143	
144	export async function adjustIngredientStock(
145	  businessId: string,
146	  ingredientId: string,
147	  newStock: number,
148	  reason: string,
149	): Promise<AdjustStockResult> {
150	  if (Number.isNaN(newStock) || newStock < 0) {
151	    return { error: "Stok fisik harus angka dan tidak boleh negatif." };
152	  }
153	  reason = reason.trim();
154	  if (!reason) {
155	    return { error: "Alasan penyesuaian wajib diisi." };
156	  }
157	
158	  const supabase = await createClient();
159	
160	  const { data: ingredient } = await supabase
161	    .from("ingredients")
162	    .select("id, name, unit, stock")
163	    .eq("id", ingredientId)
164	    .eq("business_id", businessId)
165	    .single();
166	
167	  if (!ingredient) {
168	    return { error: "Bahan baku tidak ditemukan." };
169	  }
170	
171	  const stockBefore = Number(ingredient.stock);
172	  const diff = newStock - stockBefore;
173	
174	  if (diff === 0) {
175	    return { error: "Stok fisik sama dengan stok sistem, tidak ada yang disesuaikan." };
176	  }
177	
178	  const { error: updateError } = await supabase
179	    .from("ingredients")
180	    .update({ stock: newStock })
181	    .eq("id", ingredientId);
182	
183	  if (updateError) {
184	    return { error: updateError.message };
185	  }
186	
187	  await supabase.from("stock_adjustments").insert({
188	    business_id: businessId,
189	    ingredient_id: ingredientId,
190	    item_name: ingredient.name,
191	    unit: ingredient.unit,
192	    stock_before: stockBefore,
193	    stock_after: newStock,
194	    diff,
195	    reason,
196	  });
197	
198	  await logActivity(
199	    supabase,
200	    businessId,
201	    "produk",
202	    "warning",
203	    `Penyesuaian stok: ${ingredient.name}`,
204	    `${stockBefore} → ${newStock} ${ingredient.unit} (${diff > 0 ? "+" : ""}${diff}) · ${reason}`,
205	  );
206	  revalidatePath(`/business/${businessId}/ingredients`);
207	  return { error: null };
208	}
